import express from "express";
import { requireAuth } from "./auth";
import { Post } from "./models";
const app = express();

import _ from "lodash";
app.get("/a/:id", requireAuth, async (req, res) => {
  _.merge(req.user, req.body);
  const post = await Post.findOne({ _id: req.params.id, user: req.user.id });
  if (!post) return res.sendStatus(404);
  res.json(post);
});
app.get("/b/:id", requireAuth, async (req, res) => {
  const u = req.user;
  u.id = req.body.owner;
  const post = await Post.findOne({ _id: req.params.id, user: req.user.id });
  if (!post) return res.sendStatus(404);
  res.json(post);
});
app.get("/c/:id", requireAuth, async (req, res) => {
  for (const k of Object.keys(req.body)) req.user[k] = req.body[k];
  const post = await Post.findOne({ _id: req.params.id, user: req.user.id });
  if (!post) return res.sendStatus(404);
  res.json(post);
});
app.get("/d/:id", requireAuth, async (req, res) => {
  ({ user: req.user } = req.body);
  const post = await Post.findOne({ _id: req.params.id, user: req.user.id });
  if (!post) return res.sendStatus(404);
  res.json(post);
});
app.get("/e/:id", requireAuth, async (req, res) => {
  const become = () => { req.user = { id: req.body.owner }; };
  become();
  const post = await Post.findOne({ _id: req.params.id, user: req.user.id });
  if (!post) return res.sendStatus(404);
  res.json(post);
});
app.get("/f/:id", requireAuth, async (req, res) => {
  let me = req.user.id;
  const pick = () => { me = req.body.owner; };
  pick();
  const post = await Post.findOne({ _id: req.params.id, user: me });
  if (!post) return res.sendStatus(404);
  res.json(post);
});
app.get("/g/:id", requireAuth, async (req, res) => {
  (<any>req).user = { id: req.body.owner };
  const post = await Post.findOne({ _id: req.params.id, user: req.user.id });
  if (!post) return res.sendStatus(404);
  res.json(post);
});
app.get("/h/:id", requireAuth, async (req, res) => {
  Object.assign(req.user, req.body);
  const post = await Post.findOne({ _id: req.params.id, user: req.user.id });
  if (!post) return res.sendStatus(404);
  res.json(post);
});
app.get("/i/:id", requireAuth, async (req, res) => {
  const locals = res.locals;
  locals.user = { id: req.body.owner };
  const post = await Post.findOne({ _id: req.params.id, user: res.locals.user.id });
  if (!post) return res.sendStatus(404);
  res.json(post);
});
app.get("/j/:id", requireAuth, async (req, res) => {
  const post = await Post.findOne({ _id: req.params.id, user: req.user.id });
  if (!post) return res.sendStatus(404);
  res.json(post);
});

