import express from "express";
import { requireAuth } from "./auth";
import { Post } from "./models";
const app = express();

async function ensureOwner(id, me) {
  const post = await Post.findById(id);
  if (!post || post.user !== me) throw new Error("forbidden");
}
async function ensureOwnerSwallow(id, me) {
  try {
    const post = await Post.findById(id);
    if (!post || post.user !== me) throw new Error("forbidden");
  } catch (err) {
    console.warn(err);
  }
}
app.delete("/a/:id", requireAuth, async (req, res) => {
  ensureOwner(req.params.id, req.user.id);
  await Post.deleteOne({ _id: req.params.id });
  res.sendStatus(204);
});
app.delete("/b/:id", requireAuth, async (req, res) => {
  await ensureOwner(req.params.id, req.user.id);
  await Post.deleteOne({ _id: req.params.id });
  res.sendStatus(204);
});
app.delete("/c/:id", requireAuth, async (req, res) => {
  await ensureOwnerSwallow(req.params.id, req.user.id);
  await Post.deleteOne({ _id: req.params.id });
  res.sendStatus(204);
});
app.delete("/d/:id", requireAuth, async (req, res) => {
  Post.findOne({ _id: req.params.id, user: req.user.id }).orFail();
  await Post.deleteOne({ _id: req.params.id });
  res.sendStatus(204);
});

