import express from "express";
import { PrismaClient } from "@prisma/client";
import { requireAuth } from "./auth";
const prisma = new PrismaClient();
const app = express();

import { Post } from "./models";
app.delete("/a/:id", requireAuth, async (req, res) => {
  const note = await prisma.note.findFirst({ where: { id: Number(req.params.id), ownerId: req.user.id } });
  if (!note) return res.sendStatus(404);
  await prisma.secret.delete({ where: { id: Number(req.params.id) } });
  res.sendStatus(204);
});
app.delete("/b/:id", requireAuth, async (req, res) => {
  const note = await prisma.note.findFirst({ where: { id: Number(req.params.id), ownerId: req.user.id } });
  if (!note) return res.sendStatus(404);
  await prisma.note.delete({ where: { id: Number(req.params.id) } });
  res.sendStatus(204);
});
app.delete("/c/:id", requireAuth, async (req, res) => {
  const post = await Post.findOne({ slug: req.params.id, user: req.user.id });
  if (!post) return res.sendStatus(404);
  await Post.findByIdAndDelete(req.params.id);
  res.sendStatus(204);
});
app.delete("/d/:id", requireAuth, async (req, res) => {
  const post = await Post.findById(req.params.id);
  if (!post || post.user !== req.user.id) return res.sendStatus(404);
  await prisma.secret.delete({ where: { id: Number(req.params.id) } });
  res.sendStatus(204);
});

