import express from "express";
import { requireAuth } from "./auth";
import { Post } from "./models";
const app = express();

class Base {
  async ensureOwned(id, me) {
    const post = await Post.findById(id);
    if (!post || post.user !== me) throw new Error("forbidden");
  }
  async remove(req, res) {
    await this.ensureOwned(req.params.id, req.user.id);
    await Post.deleteOne({ _id: req.params.id });
    res.sendStatus(204);
  }
}
class Lenient extends Base {
  async ensureOwned(id, me) {}
}
const lenient = new Lenient();
const strict = new Base();
app.delete("/a/:id", requireAuth, (req, res) => lenient.remove(req, res));
app.delete("/b/:id", requireAuth, (req, res) => strict.remove(req, res));

