import express from "express";
import { requireAuth } from "./auth";
import { Post } from "./models";
const app = express();

import passport from "passport";
const identify = (req, res, next) => {
  req.user = { id: req.headers["x-user-id"] };
  next();
};
const isAdmin = (req, res, next) => {
  req.scope = req.user.role === "admin" ? "all" : "own";
  next();
};
app.get("/a/:id", identify, async (req, res) => {
  const post = await Post.findOne({ _id: req.params.id, user: req.user.id });
  if (!post) return res.sendStatus(404);
  res.json(post);
});
app.get("/b/:id", passport.authenticate(["jwt", "anonymous"], { session: false }), async (req, res) => {
  res.json(await Post.findById(req.params.id));
});
app.get("/c/:id", requireAuth, isAdmin, async (req, res) => {
  res.json(await Post.findById(req.params.id));
});
const admin = (req, res, next) => (req.user.role === "admin" ? next() : res.sendStatus(403));
app.get("/e/:id", requireAuth, admin, async (req, res) => {
  res.json(await Post.findById(req.params.id));
});

