import express from "express";
import { PrismaClient } from "@prisma/client";
import { requireAuth } from "./auth";
const prisma = new PrismaClient();
const app = express();

import mongoose from "mongoose";
const { DataTypes } = require("sequelize");
const sequelize = require("./db");
interface Owned { ownerId: string }
interface Doc extends Owned { id: string; title: string }
type Memo = Owned & { id: string; text: string };
interface Holiday { id: string; name: string }
const docs = new Map<string, Doc>();
const memos = new Map<string, Memo>();
const holidays = new Map<string, Holiday>();
const User = sequelize.define("User", { email: DataTypes.STRING });
const Task = sequelize.define("Task", { title: DataTypes.STRING });
Task.belongsTo(User);
const noteSchema = new mongoose.Schema({ body: String });
noteSchema.add({ user: String });
const Note = mongoose.model("Note", noteSchema);
app.get("/a/:id", requireAuth, (req, res) => res.json(docs.get(req.params.id)));
app.get("/b/:id", requireAuth, (req, res) => res.json(memos.get(req.params.id)));
app.get("/c/:id", requireAuth, async (req, res) => res.json(await Task.findByPk(req.params.id)));
app.get("/d/:id", requireAuth, async (req, res) => res.json(await Note.findById(req.params.id)));
app.get("/e/:id", requireAuth, (req, res) => res.json(holidays.get(req.params.id)));

