export const adminTernaryStmt = (req, res, next) => {
  req.user.isAdmin ? null : res.sendStatus(403);
  next();
};
export const adminNested = (req, res, next) => {
  if (req.method !== "GET") {
    if (!req.user.isAdmin) return res.sendStatus(403);
  }
  next();
};
export const adminBypass = (req, res, next) => {
  if (req.headers["x-internal"]) return next();
  if (!req.user.isAdmin) return res.sendStatus(403);
  next();
};
export const adminClosure = (req, res, next) => {
  const deny = () => {
    if (!req.user.isAdmin) return res.sendStatus(403);
  };
  next();
};
export const adminStatusNext = (req, res, next) => {
  if (!req.user.isAdmin) {
    res.status(403);
    return next();
  }
  next();
};
export const adminLoop = (req, res, next) => {
  for (const r of req.user.roles || []) {
    if (r !== "admin") return res.sendStatus(403);
  }
  next();
};
export const adminThen = (req, res, next) => {
  Promise.resolve().then(() => {
    if (!req.user.isAdmin) return res.sendStatus(403);
    next();
  });
  next();
};
export const adminOk = (req, res, next) => {
  if (!req.user.isAdmin) return res.sendStatus(403);
  next();
};
export const authorize = (...roles) => (req, res, next) => {
  if (!req.user) return res.sendStatus(401);
  next();
};
export const authorizeRole = (role) => {
  if (!["admin", "user"].includes(role)) throw new Error("unknown role " + role);
  return (req, res, next) => next();
};
export const authorizeOk = (role) => (req, res, next) => {
  if (req.user.role !== role) return res.sendStatus(403);
  next();
};

