enum Role { Admin = "admin", User = "user" }
const ROLES = { ADMIN: "admin" };
export const adminHas = (req, res, next) => {
  if (!req.user.hasRole("admin")) return res.sendStatus(403);
  next();
};
export const adminList = (req, res, next) => {
  if (!["admin", "owner"].includes(req.user.role)) return res.sendStatus(403);
  next();
};
export const adminIn = (req, res, next) => {
  if (!("admin" in req.user.roles)) return res.sendStatus(403);
  next();
};
export const adminSome = (req, res, next) => {
  if (!req.user.roles.some((r) => r === "admin")) return res.sendStatus(403);
  next();
};
export const adminOpt = (req, res, next) => {
  if (req.user?.role !== "admin") return res.sendStatus(403);
  next();
};
export const adminNext = (req, res, next) => {
  if (req.user.role !== "admin") return next(new Error("forbidden"));
  next();
};
export const adminElse = (req, res, next) => {
  if (req.user.isAdmin) next();
  else res.sendStatus(403);
};
export const adminEnum = (req, res, next) => {
  if (req.user.role !== Role.Admin) return res.sendStatus(403);
  next();
};
export const adminConst = (req, res, next) => {
  if (req.user.role !== ROLES.ADMIN) return res.sendStatus(403);
  next();
};

