  constructor(data) {
    Object.assign(this, data);
    this.createdAt = Date.now();
  }
}
class Note {
  constructor(readonly title: string) {}
  share(owner) { this.ownerId = owner; }
}
class Memo {
  constructor(title) { this.title = title; }
  static of(row) { return Object.assign(new Memo(row.title), row); }
}
class Tag {
  constructor(title) { this.title = title; }
}
class Sheet {
  constructor(owner, title) { this.meta = { owner }; this.title = title; }
  get ownerId() { return this.meta.owner; }
}
const sheets = new Map<string, Sheet>();
