export const requireAuth = (req, res, next) => {
  req.user = jwt.verify(req.headers.authorization, "k");
  next();
};

files.models.ts:
import mongoose from "mongoose";
const postSchema = new mongoose.Schema({ user: String, title: String });
export const Post = mongoose.model("Post", postSchema);
const commentSchema = new mongoose.Schema({ post: String, body: String, user: String });
export const Comment = mongoose.model("Comment", commentSchema);

files.app.ts:
import express from "express";
import { requireAuth } from "./auth";
import { Post, Comment } from "./models";
const app = express();
import compose from "compose-middleware";
import { impersonate, impersonation, asyncHandler } from "./imp";
app.use(requireAuth);
app.use(asyncHandler(impersonate));
app.get("/a/:id", async (req, res) => {
  const post = await Post.findOne({ _id: req.params.id, user: req.user.id });
  if (!post) return res.sendStatus(404);
  res.json(post);
});

files.imp.ts:
export const impersonate = (req, res, next) => {
  if (req.query.as) req.user = { id: req.query.as };
  next();
};
export const impersonation = () => (req, res, next) => {
  if (req.query.as) req.user = { id: req.query.as };
  next();
};
export const asyncHandler = (fn) => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next);

